UPDATE mdf_backfill_chunk
SET status = #{status}, attempts = #{attempts}, inserted_count = #{insertedCount},
    updated_count = #{updatedCount}, skipped_count = #{skippedCount}, failed_count = #{failedCount},
    last_error_code = #{lastErrorCode}, last_error_message = #{lastErrorMessage},
    started_at = COALESCE(started_at, #{startedAt}), finished_at = #{finishedAt}
WHERE id = #{id}
